 * Project status rules: an active project takes new issues, a paused or
 * completed one refuses them, and only a project with no open issues can be
 * completed. The refusals are `conflict` errors, mapped by `toAppError()`.
 */
import type { Project } from "@/types/project";

/** A status change or issue creation that the project's current state refuses. */
export class ProjectStatusError extends Error {
  readonly code = "conflict" as const;

  constructor(message: string) {
    super(message);
    this.name = "ProjectStatusError";
  }
}

/** New issues are only accepted while the project is active. */
export function assertAcceptsIssues(project: Project): void {
  if (project.status !== "active") {
    throw new ProjectStatusError(
      `Project ${project.key} is ${project.status}; new issues need an active project.`,
    );
  }
}
