import type { Actor } from "@/types/member";
import type { Project, ProjectWithStats } from "@/types/project";

/** Throws unless the plan has room for one more live project. */
function assertProjectSlot(plan: PlanId, used: number): void {
  if (wouldExceedLimit(plan, "projects", used)) {
    throw new Error(`Plan ${plan} allows ${used} projects; upgrade to add another`);
  }
}

/**
 * Creates a project once the plan still has room for one. The requested
 * address and key are made unique by the repository, which also reserves the
 * addresses and keys of archived projects. The key is derived from the name
 * when the caller left it blank, so the issue numbering scheme (`TF-12`) is
 * never invented at the call site.
 */
export async function createProject(
  actor: Actor,
  input: CreateProjectInput,
): Promise<Project> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "project:create", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  assertProjectSlot(org.plan, await projectRepo.countProjects(input.orgId));

  const project = await projectRepo.insertProject({
    ...input,
    slug: input.slug || input.name,
    key: input.key || projectKeyFromName(input.name),
  });

