import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("./server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("./server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { registerUsageListeners } from "@/server/services/usage-service";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { createTenant, issueInput, useTemporaryDatabase } from "./server/_support/fixtures";
import type { CreateProjectInput } from "@/schemas/project";
import type { OrgId } from "@/types/common";

function pin(orgId: OrgId, o: Partial<CreateProjectInput> = {}): CreateProjectInput {
  return {
    orgId,
    name: "Widget Works",
    slug: "widget-works",
    key: "WID",
    description: null,
    visibility: "org",
    leadId: null,
    color: "#6366f1",
    targetDate: null,
    ...o,
  };
}

let cleanup: () => void;
let off: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  off = registerUsageListeners();
});
afterAll(() => {
  off();
  cleanup();
});

describe("verify", () => {
  it("keys: derived key collision is suffixed, archived keys reserved", async () => {
    const t = await createTenant("keys1", "growth");
    const a = await projectService.createProject(
      t.actors.member,
      pin(t.org.id, { name: "Web Visitors", slug: "web-visitors", key: "" }),
    );
    const b = await projectService.createProject(
      t.actors.member,
      pin(t.org.id, { name: "Web Vendors", slug: "web-vendors", key: "" }),
    );
    expect(a.key).toBe("WV");
    expect(b.key).toBe("WV2");

    await projectService.archiveProject(t.actors.admin, {
      orgId: t.org.id,
      projectId: a.id,
      archiveIssues: false,
    });
    const c = await projectService.createProject(
      t.actors.member,
      pin(t.org.id, { name: "Web Vault", slug: "web-vault", key: "" }),
    );
    expect(c.key).toBe("WV3");
  });

  it("keys: trimmed to four characters", async () => {
    const t = await createTenant("keys2", "growth");
    const a = await projectService.createProject(
      t.actors.member,
      pin(t.org.id, { name: "Abcd", slug: "abcd", key: "ABCD" }),
    );
    const b = await projectService.createProject(
      t.actors.member,
      pin(t.org.id, { name: "Abce", slug: "abce", key: "ABCD" }),
    );
    expect(a.key).toBe("ABCD");
    expect(b.key).toBe("ABC2");
  });

  it("addresses: archived address stays reserved; restore works", async () => {
    const t = await createTenant("slugs1", "growth");
    await projectService.archiveProject(t.actors.admin, {
      orgId: t.org.id,
      projectId: t.project.id,
      archiveIssues: false,
    });
    const fresh = await projectService.createProject(
      t.actors.member,
      pin(t.org.id, { name: "Platform", slug: "platform", key: "NEWP" }),
    );
    expect(fresh.slug).toBe("platform-2");

    const restored = await projectService.restoreProject(t.actors.admin, t.org.id, t.project.id);
    expect(restored.slug).toBe("platform");
    expect(restored.archivedAt).toBeNull();
  });

  it("plan slots: archive frees, restore takes back and refuses when full", async () => {
    const t = await createTenant("slots1", "free");
    await usageRepo.recomputeUsage(t.org.id);
    const base = (await usageRepo.getUsage(t.org.id)).projectsUsed;
    expect(base).toBe(1);

    await projectService.archiveProject(t.actors.admin, {
      orgId: t.org.id,
      projectId: t.project.id,
      archiveIssues: false,
    });
    expect((await usageRepo.getUsage(t.org.id)).projectsUsed).toBe(0);
    expect(await projectRepo.countProjects(t.org.id)).toBe(0);

    await projectService.createProject(
      t.actors.member,
      pin(t.org.id, { name: "Second Project", slug: "second", key: "SEC" }),
    );
    await projectService.createProject(
      t.actors.member,
      pin(t.org.id, { name: "Third Project", slug: "third", key: "THI" }),
    );
    expect((await usageRepo.getUsage(t.org.id)).projectsUsed).toBe(2);

    const received: unknown[] = [];
    const offR = subscribe("project.restored", (p) => {
      received.push(p);
    });
    try {
      await expect(
        projectService.restoreProject(t.actors.admin, t.org.id, t.project.id),
      ).rejects.toThrow(/allows 2 projects/);
      expect(received).toHaveLength(0);
      expect((await usageRepo.getUsage(t.org.id)).projectsUsed).toBe(2);
      const stored = await projectRepo.findProjectById(t.org.id, t.project.id);
      expect(stored?.archivedAt).not.toBeNull();
    } finally {
      offR();
    }

    // Recount agrees with the meter.
    const recount = await usageRepo.recomputeUsage(t.org.id);
    expect(recount.projectsUsed).toBe(2);
  });

  it("restore: not-archived is refused and announces nothing", async () => {
    const t = await createTenant("restore1", "growth");
    const received: unknown[] = [];
    const offR = subscribe("project.restored", (p) => {
      received.push(p);
    });
    try {
      await expect(
        projectService.restoreProject(t.actors.admin, t.org.id, t.project.id),
      ).rejects.toThrow(/not archived/);
      expect(received).toHaveLength(0);
    } finally {
      offR();
    }
  });

  it("restore keeps status and archived issues archived", async () => {
    const t = await createTenant("restore2", "growth");
    const issue = await issueService.createIssue(
      t.actors.member,
      issueInput(t.org.id, t.project.id, { title: "x" }),
    );
    await projectService.updateProject(t.actors.admin, {
      orgId: t.org.id,
      projectId: t.project.id,
      status: "paused",
    });
    await projectService.archiveProject(t.actors.admin, {
      orgId: t.org.id,
      projectId: t.project.id,
      archiveIssues: true,
    });
    const restored = await projectService.restoreProject(t.actors.admin, t.org.id, t.project.id);
    expect(restored.status).toBe("paused");
    expect((await issueRepo.findIssueById(t.org.id, issue.id))?.archivedAt).not.toBeNull();
  });

  it("status: saved, filterable, refuses issues when paused; no event", async () => {
    const t = await createTenant("status1", "growth");
    const paused = await projectService.updateProject(t.actors.admin, {
      orgId: t.org.id,
      projectId: t.project.id,
      status: "paused",
    });
    expect(paused.status).toBe("paused");

    const page = await projectService.listProjects(t.actors.admin, {
      orgId: t.org.id,
      limit: 50,
      cursor: null,
      status: "paused",
    } as never);
    expect(page.items.map((r) => r.project.id)).toContain(t.project.id);

    const before = await issueRepo.countIssues(t.org.id, t.project.id);
    const received: unknown[] = [];
    const offI = subscribe("issue.created", (p) => {
      received.push(p);
    });
    try {
      await expect(
        issueService.createIssue(
          t.actors.member,
          issueInput(t.org.id, t.project.id, { title: "nope" }),
        ),
      ).rejects.toThrow(/active/);
      expect(received).toHaveLength(0);
      expect(await issueRepo.countIssues(t.org.id, t.project.id)).toBe(before);
    } finally {
      offI();
    }

    const active = await projectService.updateProject(t.actors.admin, {
      orgId: t.org.id,
      projectId: t.project.id,
      status: "active",
    });
    expect(active.status).toBe("active");
  });

  it("status: completion refused with open issues; allowed with done/canceled/archived", async () => {
    const t = await createTenant("status2", "growth");
    const open = await issueService.createIssue(
      t.actors.member,
      issueInput(t.org.id, t.project.id, { title: "open" }),
    );
    const done = await issueService.createIssue(
      t.actors.member,
      issueInput(t.org.id, t.project.id, { title: "done" }),
    );
    const canceled = await issueService.createIssue(
      t.actors.member,
      issueInput(t.org.id, t.project.id, { title: "canceled" }),
    );
    await issueService.changeIssueStatus(t.actors.member, {
      orgId: t.org.id,
      issueId: done.id,
      status: "done",
    });
    await issueService.changeIssueStatus(t.actors.member, {
      orgId: t.org.id,
      issueId: canceled.id,
      status: "canceled",
    });

    await expect(
      projectService.updateProject(t.actors.admin, {
        orgId: t.org.id,
        projectId: t.project.id,
        status: "completed",
        name: "Renamed Too",
      }),
    ).rejects.toThrow(/open issue/);
    const unchanged = await projectRepo.findProjectById(t.org.id, t.project.id);
    expect(unchanged?.status).toBe("active");
    expect(unchanged?.name).toBe(t.project.name);

    await issueService.archiveIssue(t.actors.admin, t.org.id, open.id);
    const completed = await projectService.updateProject(t.actors.admin, {
      orgId: t.org.id,
      projectId: t.project.id,
      status: "completed",
    });
    expect(completed.status).toBe("completed");

    // Completing again changes nothing and is not refused.
    const again = await projectService.updateProject(t.actors.admin, {
      orgId: t.org.id,
      projectId: t.project.id,
      status: "completed",
    });
    expect(again.status).toBe("completed");

    // Completed project refuses new issues.
    await expect(
      issueService.createIssue(
        t.actors.member,
        issueInput(t.org.id, t.project.id, { title: "late" }),
      ),
    ).rejects.toThrow(/active/);

    // Reactivating and pausing are always allowed.
    await projectService.updateProject(t.actors.admin, {
      orgId: t.org.id,
      projectId: t.project.id,
      status: "paused",
    });
  });

  it("status: archived project status cannot change", async () => {
    const t = await createTenant("status3", "growth");
    await projectService.archiveProject(t.actors.admin, {
      orgId: t.org.id,
      projectId: t.project.id,
      archiveIssues: false,
    });
    await expect(
      projectService.updateProject(t.actors.admin, {
        orgId: t.org.id,
        projectId: t.project.id,
        status: "paused",
      }),
    ).rejects.toThrow(/already archived/);
  });
});
